  "implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    if n == 0:
        return {'selected_indices': [], 'tokens_used': 0, 'total_score': 0.0}
    best_overall = None
    # dp[t] = (score, tokens, indices_tuple) for best solution using processed items
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, ())
    for i in range(n):
        length = lengths[i]
        score = scores[i]
        new_dp = dp[:]  # copy (not including current item)
        for t in range(length, budget + 1):
            if dp[t - length] is not None:
                prev_score, prev_tokens, prev_indices = dp[t - length]
                cand_score = prev_score + score
                cand_tokens = prev_tokens + length
                cand_indices = prev_indices + (i,)
                cand = (cand_score, cand_tokens, cand_indices)
                cur = new_dp[t]
                if cur is None:
                    new_dp[t] = cand
                else:
                    # compare: higher score, then less tokens, then lexicographic indices
                    # use tuple key: (-score, tokens, indices) and take min
                    key_cand = (-cand_score, cand_tokens, cand_indices)
                    key_cur = (-cur[0], cur[1], cur[2])
                    if key_cand < key_cur:
                        new_dp[t] = cand
        dp = new_dp
    # find best overall among all feasible t
    for t in range(budget + 1):
        if dp[t] is not None:
            if best_overall is None:
                best_overall = dp[t]
            else:
                key_cand = (-dp[t][0], dp[t][1], dp[t][2])
                key_best = (-best_overall[0], best_overall[1], best_overall[2])
                if key_cand < key_best:
                    best_overall = dp[t]
    best_score, best_tokens, best_indices = best_overall
    return {
        'selected_indices': list(best_indices),
        'tokens_used': best_tokens,
        'total_score': best_score
    }"
}
